    best=None
    for s in range(seeds):
        p0=np.random.RandomState(s).uniform(-0.5,1.5,n)
        try:
            r=least_squares(lambda p: fn(p,t,A)-dA_dt, p0, max_nfev=4000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return np.round(best.x,5), np.sqrt(np.mean(best.fun**2))/np.std(dA_dt)
